<?php require_once __DIR__.'/_layout.php'; admin_header('Đơn hàng','orders'); admin_flash(); $pdo=db(); $orders=$pdo?$pdo->query('SELECT o.*,COUNT(i.id) item_count FROM orders o LEFT JOIN order_items i ON i.order_id=o.id GROUP BY o.id ORDER BY o.id DESC')->fetchAll(PDO::FETCH_ASSOC):[]; ?>
<div class="admin-card"><div class="card-head"><div><h2>Đơn đặt hàng</h2><p>Yêu cầu từ website</p></div></div><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Sản phẩm</th><th>Tổng tiền</th><th>Trạng thái</th><th>Ngày tạo</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><a href="order-detail.php?id=<?=$o['id']?>"><b><?=htmlspecialchars($o['order_code'])?></b></a></td><td><?=htmlspecialchars($o['customer_name'])?><br><small><?=htmlspecialchars($o['phone'])?></small></td><td><?=$o['item_count']?> sản phẩm</td><td><?=number_format($o['subtotal'],0,',','.')?>đ</td><td><span class="status <?=htmlspecialchars($o['status'])?>"><?=htmlspecialchars($o['status'])?></span></td><td><?=htmlspecialchars($o['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></div><?php admin_footer(); ?>
